impl From<TaskDiffDetail> for HistoryTaskDiffProjection {
    fn from(detail: TaskDiffDetail) -> Self {
        let differences = find_json_differences(&detail.previous_output, &detail.current_output);
        Self {
            detail,
            differences,
        }
    }
}

