#[allow(clippy::too_many_arguments)]
fn nav_button(
    palette: Palette,
    icon: FaIcon,
    label: &'static str,
    selected: bool,
    expanded: bool,
    badge: Option<&str>,
    action: Callback<()>,
    enabled: bool,
) -> View {
    let content: View = if expanded {
        let badge: View = if let Some(value) = badge {
            Border::new()
                .grid_column(2)
                .min_width(18.0)
                .height(18.0)
                .padding(Thickness::xy(5.0, 0.0))
                .background(palette.warn_bg)
                .corner_radius(999.0)
                .vertical_alignment(VerticalAlignment::Center)
                .content(
                    TextBlock::new()
                        .text(value)
                        .font_size(10.5)
                        .font_weight(FontWeight::BOLD)
                        .foreground(palette.warn)
                        .horizontal_alignment(HorizontalAlignment::Center),
                )
        } else {
            View::empty()
        };
        Grid::new()
            .columns([
                GridLength::Pixel(17.0),
                GridLength::Star(1.0),
                GridLength::Auto,
            ])
            .column_spacing(11.0)
            .children((
                icons::path(icon),
                TextBlock::new()
                    .text(label)
                    .grid_column(1)
                    .font_size(13.0)
                    .font_weight(if selected {
                        FontWeight::SEMI_BOLD
                    } else {
                        FontWeight::NORMAL
                    })
                    .vertical_alignment(VerticalAlignment::Center),
                badge,
            ))
    } else {
        icons::path(icon).into()
    };

    let button = Button::new()
        .height(37.0)
        .horizontal_alignment(HorizontalAlignment::Stretch)
        .horizontal_content_alignment(if expanded {
            HorizontalAlignment::Left
        } else {
            HorizontalAlignment::Center
        })
        .resource_overrides(
            ResourceOverrides::new()
                .set(
                    "ButtonBackground",
                    if selected {
                        palette.active
                    } else {
                        Color::transparent()
                    },
                )
                .set("ButtonBackgroundDisabled", Color::transparent())
                .set("ButtonBackgroundPointerOver", palette.card)
                .set("ButtonBackgroundPressed", palette.active)
                .set("ButtonForeground", palette.text)
                .set("ButtonForegroundDisabled", palette.muted)
                .set("ButtonBorderBrushDisabled", Color::transparent())
                .set("ButtonBorderThemeThickness", Thickness::uniform(0.0))
                .set(
                    "ButtonPadding",
                    if expanded {
                        Thickness::xy(11.0, 0.0)
                    } else {
                        Thickness::uniform(0.0)
                    },
                )
                .set("ControlCornerRadius", CornerRadius::uniform(6.0)),
        )
        .is_enabled(enabled)
        .on_click(action)
        .automation_name(label)
        .content(content);

    if selected {
        Grid::new().children((
            button,
            Border::new()
                .width(3.0)
                .height(17.0)
                .margin(Thickness::new(0.0, 0.0, 0.0, 0.0))
                .background(palette.accent)
                .corner_radius(999.0)
                .horizontal_alignment(HorizontalAlignment::Left)
                .vertical_alignment(VerticalAlignment::Center),
        ))
    } else {
        button
    }
}

