    #[test]
    fn global_shortcut_policy_matches_shipping_overlay_and_editable_guards() {
        use window_support::{GlobalShortcutCommand as Command, GlobalShortcutEvent as Event};

        let commands = [
            Command::TogglePalette,
            Command::Navigate(1),
            Command::ShowHelp,
            Command::QuickScan,
            Command::FullScan,
        ];
        for command in commands {
            assert!(global_shortcut_is_allowed(
                Event {
                    command,
                    editable_focused: false,
                },
                false,
                false,
                false,
            ));
            assert!(!global_shortcut_is_allowed(
                Event {
                    command,
                    editable_focused: false,
                },
                true,
                false,
                false,
            ));
        }

        assert!(global_shortcut_is_allowed(
            Event {
                command: Command::TogglePalette,
                editable_focused: true,
            },
            false,
            false,
            false,
        ));
        for command in [
            Command::Navigate(2),
            Command::ShowHelp,
            Command::QuickScan,
            Command::FullScan,
        ] {
            assert!(!global_shortcut_is_allowed(
                Event {
                    command,
                    editable_focused: true,
                },
                false,
                false,
                false,
            ));
        }

        for command in [
            Command::PalettePrevious,
            Command::PaletteNext,
            Command::PaletteExecute,
            Command::PaletteClose,
        ] {
            assert!(!global_shortcut_is_allowed(
                Event {
                    command,
                    editable_focused: true,
                },
                false,
                false,
                false,
            ));
            assert!(global_shortcut_is_allowed(
                Event {
                    command,
                    editable_focused: true,
                },
                true,
                true,
                false,
            ));
        }
        assert!(global_shortcut_is_allowed(
            Event {
                command: Command::TogglePalette,
                editable_focused: true,
            },
            true,
            true,
            false,
        ));
    }

